# The tables keep each Iowa note's own level, and that scatters +-5 dB from note to note (the player's level in the
# run, not the flute: Iowa vib mf C#5 +5.8 dB and E5 -4.6 dB off a smooth register curve), so a song line's landing
# E5 and D5 sat 6 dB under the C5 and G5 beside them. LEVEL_EVEN of that
# scatter is taken out: each note's harmonics move together to a quadratic fit of the level over the register, per
# dynamic and tone set (the colour, the harmonics re each other and the air re the tone, is unchanged).
LEVEL_EVEN = 1.0


def _level_fix(tab):
    T = np.asarray(tab, float)
    m = np.asarray(FIT_MIDI, float)
    P = 10 * np.log10(np.sum(10 ** (T / 10), axis=2))
    fix = np.zeros(P.shape)
    for d in range(P.shape[1]):
        fix[:, d] = np.polyval(np.polyfit(m, P[:, d], 2), m) - P[:, d]
    return fix


def _level_of(tab):
    return 10 * np.log10(np.sum(10 ** (np.asarray(tab, float) / 10), axis=2))


LEVEL_MODE = 1.0          # 0: both sets to the register fit; 1: the vib set to the non-vib set's own levels
if LEVEL_MODE:
    FIX_H, FIX_HV = np.zeros_like(_level_of(FIT_H)), _level_of(FIT_H) - _level_of(FIT_HV)
else:
    FIX_H, FIX_HV = _level_fix(FIT_H), _level_fix(FIT_HV)

