SLUR_X_NZ_HZ = (1200.0, 5000.0)    # ... and its band, Hz
# The next picture judges read that burst as a tell ("sharp broadband vertical stripes, click-like"). Per band:
# jband: the real joins rise softly in every band (0.3-1.5 / 1.5-5 / 5-10 kHz +5.4 / +6.2 / +4.8 dB for 23 / 31 / 20 ms,
# sharpness 0.4 / 2.3 / 3.8 dB); ours with the burst +2.9 / +3.3 / +8.9 for 4 / 10 / 24 ms, sharpness 1.4 / 0.6 / 8.7
# (the burst's 2nd-order band leaks over 5 kHz where the floor is low). So the burst becomes a swell of the air itself
# (its own spectrum, so no band of its own), SLUR_X_SWELL x the held air at the peak (per slur x lognormal 0.3), a
# gaussian of SLUR_X_SWELL_MS (peak 2 widths after the join), and the noise burst is off (SLUR_X_BURST 0; 1 brings the round 11 burst back).
SLUR_X_BURST = 0.0
SLUR_X_SWELL = 1.0
SLUR_X_SWELL_MS = 12.0
SLUR_X_SOFT_DB = -6.0      # ... and a soft noise under 2.5 kHz (the real's 0.3-5 kHz rise is not the air's: the swell moves
SLUR_X_SOFT_MS = 14.0      # 5-10 kHz most): re the tongue chiff's scale (per slur +-3 dB), a gaussian of this (peak 2
SLUR_X_SOFT_LO = 300.0     # widths after the join), its band (4th-order edges) from this ...
SLUR_X_SOFT_HI = 2500.0    # ... to this, Hz
# Kept (legato direct): 5-10 kHz +8.9 dB / 24 ms / sharpness 8.7 to +4.9 / 18 / 5.0 (real +4.8 / 20 / 3.8), legato
# 12.45 to 12.09. 0.3-1.5 kHz did not move (+2.9, real +5.4), 1.5-5 kHz +3.3 (real +6.2). Tries: swell only 12.46;
# soft 0 dB to 4 kHz 11.49 but 5-10 kHz +10.0 (sharp 6.9, its top edge over the weak floor there); -3 dB to 3.5 kHz
# 11.75, 5-10 kHz +6.4 (sharp 5.5).
# The floor between the partials, a texture (a picture judge: the real's "darker and patchier floor with dark
# speckles", ours "bright and even"). The air goes through an STFT (1024 points, hop 256) and each cell's level
# is a smooth random field (AIR_PATCH_DB sd, knots every AIR_PATCH_F Hz and AIR_PATCH_T s, from AIR_PATCH_HZ up
# over an octave), at the same mean power. Played by the param air_patch (default 0).
# Kept at 4 dB, none at pp, on the tone, Syrinx, legato and staccato demos (floor, mean of 11 pairs, real /
# before / after): floor re partials 3-6k -33.0 / -30.8 / -31.7, 6-10k -23.8 / -20.1 / -21.2 dB; patchiness 5.7 / 4.5 / 4.8,
# 4.1 / 3.1 / 3.5 dB. Distances ff C4 4.77 to 4.86, G5 5.64 to 5.70, C6 6.74 to 6.78, Syrinx 6.42 to 6.36, legato 12.09 to
# 12.06, staccato 11.11 to 11.07.
AIR_PATCH_DB = 4.0      # try 1 at 6 dB and every dynamic: floor 6-10k -24.3 (real -23.8) but vib pp G4 5.25 to 6.14, pp C4 +0.22
AIR_PATCH_F = 150.0
AIR_PATCH_T = 0.04
AIR_PATCH_HZ = 1000.0
REL_AIR = 0.95            # r7: the air's release time re the tone's (1.3 before r7: the noise 3-8 kHz took 58 ms to fall 10 dB
                          # at C6 ff, real 45; 0.8 gave 39)
INHALE_DB = -34.0         # inhale level re the phrase's tone at inhale 1
FLUTTER_DEPTH = 0.8
FLUT_SHAPE = 1.0          # r6, flap shape, (0.5 + 0.5 cos) ** this: 2 (before) = short deep cuts (thin dark stripes through the
                          # whole spectrum), 1 = rounder, wider
FLUT_JIT = 0.25           # flutter roll timing wander, share of the rate ...
FLUT_JIT_HZ = 12.0        # ... knots a second ...
FLUT_LEVEL = 0.0          # share of the flap on the level instead of the blowing (r5: 0.5 and 1.0 tried, the
                          # measured depth fell and the distance rose, so 0)
FLUT_AMP_SD = 0.5         # ... and each roll's own depth (wander sd, knots at the roll rate)
PARTIAL_WANDER_DB = 1.5
PARTIAL_WANDER_HZ = 6.0
COMB_DB = 0.0             # r8, tried twice, not kept (0): slow independent level wander per partial (H2 up, full from H3), dB, knots COMB_HZ a
COMB_HZ = 2.0             # second, full under COMB_MIDI[0] and none over COMB_MIDI[1] (picture judges: 'an even comb
COMB_MIDI = (70.0, 79.0)  # of equal brightness'; Iowa C4 / A4 partials H2-H12 move 2.3-4.0 dB rms over 0.25 s, ours
                          # 1.0; G5, C6 1.2 / 0.9, ours the same). 0 = as before r8
COMB_B = (-20.0, 0.0)     # ... and none at this blowing (pp), full at this (ff): the louder notes wander most (Iowa ff C4
                          # 4.0 dB, mf A4 3.9, pp C4 2.3, pp G4 1.3); None: every dynamic in full. Try 1 (3 dB, 2 Hz,
                          # None): slow C4 pp / ff / A4 1.0 / 1.0 / 1.2 to 2.3 / 2.4 / 2.1, but held pairs 41.09 to 42.03,
                          # legato 12.74 to 13.43. Try 2 (with COMB_B): ff C4 4.93 to 4.40, held 41.09 to 40.77, but
                          # legato 13.10 and the 11 pairs 87.27 to 87.34
TAIL_DB_OCT = -15.0       # r8: the harmonics past the 12-harmonic tables (None: as before r8, the table's last slope run
TAIL_SOFT = 7.5           # on, which fell 5-9 dB per harmonic at ff C4 and stopped the comb near 3 kHz, the picture judges'
                          # shared cue). Now from the mean of H12 and H10-H12, falling this many dB per octave of
                          # harmonic number at ff, TAIL_SOFT dB/oct steeper per 10 dB softer blowing (Iowa ff C4: H13-H20
                          # -35 to -42 dB re the top, 13-22 dB over the floor, to 11 kHz; pp C4 falls faster, H16 -65),
                          # up to 60 harmonics (15 kHz)
PHASE_SPREAD = 0.3
JITTER_CENTS = 1.8        # fast pitch unsteadiness, cents rms (knots ~22 a second)
FLICKER_DB = 2.4          # fast per-partial level flicker from H3 up, dB rms (knots ~18 a second)


def _rng(seed, ms, salt):
    return np.random.default_rng([int(seed) & 0xFFFFFFFF, int(ms) + (1 << 40), int(salt) & 0xFFFF])


def _song_ms(st, beat0, bpm):
    return int(round((st + beat0 * 60.0 / bpm) * 1000))


def _smooth_f0(f0, n=64):
    """the played pitch per sample without its fastest wobble (a 64-sample running mean), for the air's comb"""
    k = np.ones(n) / n
    return np.convolve(np.pad(f0, (n // 2, n - 1 - n // 2), mode='edge'), k, mode='valid')


def _wander(n_ctrl, cr, rate_hz, rng):
    step = max(2, int(cr / rate_hz))
    knots = rng.normal(0, 1, n_ctrl // step + 3)
    x = np.arange(n_ctrl) / step
    i = np.floor(x).astype(int)
    f = x - i
    f = f * f * (3 - 2 * f)
    return knots[i] * (1 - f) + knots[i + 1] * f


def _smooth(f):
    f = np.clip(f, 0, 1)
    return f * f * (3 - 2 * f)


def _blow(v):
    """velocity 0..1 -> blowing on the table axis (FIT_B: pp -20, mf -10, ff 0)."""
    return np.interp(v * 127.0, [0.0, 20.0, 40.0, 80.0, 127.0], [-35.0, -28.0, -20.0, -10.0, 0.0])


def _interp2(tab, midi, b):
    """tab[midi_i][dyn_i] -> array (per control frame): linear in midi over FIT_MIDI and in blowing over FIT_B."""
    T = np.asarray(tab, float)                     # (nm, nd, ...)
    fm = np.asarray(FIT_MIDI, float)
    fb = np.asarray(FIT_B, float)
    mi = np.clip(np.searchsorted(fm, midi) - 1, 0, len(fm) - 2)
    mf = np.clip((midi - fm[mi]) / (fm[mi + 1] - fm[mi]), 0, 1)
    bi = np.clip(np.searchsorted(fb, b) - 1, 0, len(fb) - 2)
    bf = (b - fb[bi]) / (fb[bi + 1] - fb[bi])
    bf = np.clip(bf, -0.6, 1.25)                   # a little beyond pp (softer, airier) and past ff
    ex = (Ellipsis,) + (None,) * (T.ndim - 2)
    a00, a01 = T[mi, bi], T[mi, bi + 1]
    a10, a11 = T[mi + 1, bi], T[mi + 1, bi + 1]
    mf_, bf_ = mf[ex], bf[ex]
    lo = a00 + (a01 - a00) * bf_
    hi = a10 + (a11 - a10) * bf_
    return lo + (hi - lo) * mf_


def perform(notes, total_n, sr, bpm=120.0, lanes=None, beat0=0.0, **params):
    P = dict(DEFAULTS)
    P.update({k: v for k, v in params.items() if v is not None and k in DEFAULTS})
    lanes = lanes or {}
    out = np.zeros(total_n)
    if not notes:
        return np.zeros((2, total_n))
    CR = 64
    seed = int(P['seed'])
    nh_tab = len(np.asarray(FIT_H)[0, 0])

    def lane_at(name, i, default):
        c = lanes.get(name)
        if c is None or len(c) == 0:
            return float(default)
        return float(c[int(np.clip(i, 0, len(c) - 1))])

    ns = sorted([(float(n[0]), float(n[1]), float(n[2]), float(n[3]) / 127.0) for n in notes], key=lambda z: (z[0], -z[1]))
    phrases = []
    for st, m, d, v in ns:
        if d <= 0:
            continue
        if phrases and st < phrases[-1][-1][0] + phrases[-1][-1][2] - 1e-3 and st > phrases[-1][-1][0] + 1e-3:
            phrases[-1].append((st, m, d, v, False))              # overlap: slurred
        elif phrases and 0 <= st - (phrases[-1][-1][0] + phrases[-1][-1][2]) < TONGUE_GAP:
            phrases[-1].append((st, m, d, v, True))               # a short gap: tongued under the same breath
        else:
            phrases.append([(st, m, d, v, False)])
    ev = float(P['entry_vel'])
    if ev:
        # a pickup (a phrase's first note shorter than a beat) is blown a little firmer: under a breath attack it
        # read 7 to 14 dB under the note it leads to
        for ph in phrases:
            st, m, d, v, tgd = ph[0]
            if d * bpm / 60.0 < 1.0:
                ph[0] = (st, m, d, min(v + ev / 127.0, 1.0), tgd)

    rel = float(P['release'])
    gap_s = float(P['breath_gap'])
    prev_end = None
    for ph in phrases:
        p0 = ph[0][0]
        p_end = ph[-1][0] + ph[-1][2]
        # an inhale before the phrase when the silence before it is a breath
        inh = float(P['inhale'])
        gap = p0 - prev_end if prev_end is not None else 1.0
        do_inhale = inh > 0 and gap >= gap_s
        inh_len = min(0.35, max(0.12, gap - 0.08)) if do_inhale else 0.0
        prev_end = p_end
        lead = 0.25                                             # room before the first note for its air
        a = int(round((p0 - lead - inh_len) * sr))
        b = int(round((p_end + rel + 0.05) * sr))
        if b <= 0 or a >= total_n:
            continue
        n = b - a
        nc = n // CR + 2
        tc = (np.arange(nc) * CR) / sr - lead - inh_len          # seconds re the phrase start
        crate = sr / CR
        ms0 = _song_ms(p0, beat0, bpm)
        prng = _rng(seed, ms0, 1)

        midi = np.full(nc, ph[0][1])
        vel = np.full(nc, ph[0][3])
        tone = np.zeros(nc)                                     # 0..1 tone gate (attack/release shape)
        airg = np.zeros(nc)                                     # 0..1 air gate
        note_age = np.zeros(nc)
        vsc = np.ones(nc)                                       # per-note vibrato depth (players vary it note to note)
        vdl = np.full(nc, float(P['vib_delay']))
        blow_db = np.zeros(nc)                                  # blowing (colour axis of the tables)
        gain_db = np.zeros(nc)                                  # straight level changes (slur dips, fall fades)
        tgap_db = np.zeros(nc)                                  # r13 tgap_shape: the extra tongue dip, partials under TGAP_HZ
        bend_extra = np.zeros(nc)
        glide = np.zeros(nc)                                    # the slur's pitch glide alone (semitones), for the colour
        air_burst = np.zeros(nc)
        lag_c = np.zeros(nc)                                    # upper-harmonic lag at the attack (s)
        chiff = []
        keyt = []
        vhold = []                                              # (frame, vib lane value at the note's start)
        rel_at = []                                             # the phrase's release: (frame, frames, tone gate)
        sup = []                                                # slurs (slur_detail): (crossing s, upper-harmonic dip dB)
        xfd = []                                                # slurs (slur_cross): (frame, old midi, song ms)
        scr = float(np.clip(P['slur_cross'], 0.0, 1.0))
        for j, (st, m, d, v, tgd) in enumerate(ph):
            i0 = int(np.clip(round((st - p0 + lead + inh_len) * sr / CR), 0, nc - 1))
            i1 = int(np.clip(round((st + d - p0 + lead + inh_len) * sr / CR), i0 + 1, nc - 1))
            nrng = _rng(seed, _song_ms(st, beat0, bpm), 2)
            midi[i0:] = m + nrng.normal(0, 0.03)
            vel[i0:] = v * np.exp(nrng.normal(0, 0.03))
            vsc[i0:] = np.exp(_rng(seed, _song_ms(st, beat0, bpm), 12).normal(0, VIB_NOTE_SD))
            vdl[i0:] = float(P['vib_delay']) * np.exp(_rng(seed, _song_ms(st, beat0, bpm), 13).normal(0, 0.35))
            note_age[i0:] = tc[i0:] - tc[i0]
            s_glob = a + i0 * CR
            e_glob = a + i1 * CR
            t_rel = tc[i0:] - tc[i0]
            b_note = _blow(v)
            vhold.append((i0, lane_at('vib', s_glob, P['vib'])))
            if j == 0:
                tg = float(np.clip(lane_at('tongue', s_glob, P['tongue']), 0, 1))
                att = float(_interp2(FIT_ATT, np.array([m]), np.array([b_note]))[0]) / 1000.0
                att *= (1.9 - 1.2 * tg) * np.exp(nrng.normal(0, 0.12))   # breath attack slower, hard tongue faster
                if ATT_SHORT > 0:
                    # a short tongued note cannot swell in: the tongue releases the air at once (staccato)
                    att = min(att, max(ATT_SHORT * d / (0.2 + 0.8 * tg), 0.004))
                lagv = float(_interp2(FIT_LAG, np.array([m]), np.array([b_note]))[0]) / 1000.0 * (1.6 - 0.8 * tg)
                soft = float(np.clip(-b_note / 20.0, 0, 1.5))
                alead = (ATT_AIR_LEAD + ATT_AIR_SOFT * soft) * (2.0 - 1.6 * tg) / 1.04
                rise = _smooth((tc - tc[i0]) / max(att / 0.8, 1e-3))
                tone = np.maximum(tone, rise * (tc >= tc[i0]))
                ar = _smooth((tc - tc[i0] + alead) / max(alead, 0.004))
                airg = np.maximum(airg, ar)
                lag_c[:] = lagv
                chiff.append((i0, tg ** 1.5 * (0.4 + 0.6 * v)))
                oc = float(P['onset_cents']) * (0.4 + 0.6 * tg) / 100.0
                bend_extra[i0:] += oc * np.exp(-t_rel / 0.04)
            elif tgd:
                # legato tonguing: the air keeps going, the tongue cuts it for the gap and a few ms, a chiff
                pm = ph[j - 1][1]
                tg = float(np.clip(lane_at('tongue', s_glob, P['tongue']), 0, 1))
                pe = ph[j - 1][0] + ph[j - 1][2]
                ta, tb = pe - p0 + lead + inh_len - 0.012, st - p0 + lead + inh_len + 0.018
                x = np.clip((tc + lead + inh_len - ta) / max(tb - ta, 0.01), 0, 1)
                bump = np.sin(np.pi * x) ** 0.8 * ((x > 0) & (x < 1))
                tgs = float(P['tgap_shape'])                    # r13: the tone dips deeper, the air carries on
                gain_db += TONGUE_DIP_DB * (0.5 + 0.5 * tg) * bump
                tgap_db += TONGUE_DIP_DB * (0.5 + 0.5 * tg) * tgs * (TGAP_TONE - 1) * bump   # under TGAP_HZ only
                air_burst -= 0.7 * (1 + tgs * (TGAP_AIR - 1)) * bump
                bend_extra[i0:] += (pm - m) * (1 - _smooth(t_rel / 0.006))
                glide[i0:] += (pm - m) * (1 - _smooth(t_rel / 0.006))
                bend_extra[i0:] += float(P['onset_cents']) * 0.5 * tg / 100.0 * np.exp(-t_rel / 0.03)
                chiff.append((i0, 0.7 * tg ** 1.5 * (0.4 + 0.6 * v), _song_ms(st, beat0, bpm)))
            else:
                pm = ph[j - 1][1]
                sl = max(0.006, float(P['slur_ms']) / 1000 * (1 + 0.25 * nrng.normal()))
                if scr > 0:
                    # r11: the fingers' move is almost instant, the old note rings on under the new (cross-fade below)
                    sl = (1 - scr) * sl + scr * SLUR_X_MS / 1000
                    xfd.append((i0, float(midi[max(i0 - 1, 0)]), _song_ms(st, beat0, bpm)))
                    if SLUR_X_SWELL > 0:
                        wrng = _rng(seed, _song_ms(st, beat0, bpm), 24)
                        air_burst[i0:] += scr * SLUR_X_SWELL * float(np.exp(wrng.normal(0, 0.3))) * np.exp(
                            -(t_rel / (SLUR_X_SWELL_MS / 1000) - 2.0) ** 2)    # peak 2 widths after the join, so it starts from 0
                x = t_rel / sl
                # each slur moves differently (Syrinx, Philharmonia: 10-90 % in 2-21 ms, fast or slow start, the
                # pitch passing the new note by about 12 c and settling): a skewed move and an overshoot, per slur
                srng = _rng(seed, _song_ms(st, beat0, bpm), 22)
                sdet = float(np.clip(P['slur_detail'], 0.0, 1.0))
                q = float(np.exp(srng.normal(0, SLUR_SKEW) * sdet))
                xs = np.clip(x, 0, 1) ** q
                ov = sdet * SLUR_OVER_C / 100.0 * float(np.exp(srng.normal(0, 0.5))) * np.sign(m - pm)
                ovc = _smooth(x / 0.8) * np.exp(-np.maximum(t_rel - 0.8 * sl, 0) / (SLUR_OVER_MS / 1000))
                bend_extra[i0:] += (pm - m) * (1 - _smooth(xs)) + ov * ovc
                glide[i0:] += (pm - m) * (1 - (_smooth(t_rel / (COL_MS / 1000)) if COL_MS > 0 else _smooth(xs)))
                jump = min(1.0, abs(m - pm) / 12.0)
                g = np.exp(-((t_rel - sl * 0.5) / max(sl * 0.8, 0.012)) ** 2)
                blow_db[i0:] += 0.5 * float(P['slur_dip']) * (0.4 + 0.6 * jump) * g
                # the level: a short gap while the fingers cross (real: -6 dB in 5 ms frames, about 12 ms under
                # -3 dB, read as only -2 dB in 10 ms frames), not a wide shallow dip
                # (slur_detail 0 keeps the wide shallow dip of round 3)
                gw = SLUR_GAP_MS / 1000 * float(np.exp(srng.normal(0, 0.3)))
                gg = np.exp(-((t_rel - sl * 0.5 * q ** -0.5) / gw) ** 2)
                sdip = float(P['slur_dip'])
                gain_db[i0:] += ((1 - sdet) * sdip * (0.5 + 0.5 * jump) * g +
                                 sdet * (SLUR_GAP_DB + 2.0 * srng.normal()) * (0.5 + 0.5 * jump) * gg)
                air_burst[i0:] += SLUR_AIR * (0.3 + 0.7 * jump) * g
                keyt.append(i0)
                if sdet > 0:
                    # the jet re-forms on the new note: the upper harmonics drop out as the fingers cross and come
                    # back late (Philharmonia legato slurs of 3-4 semitones: H3-H6 -16 dB 10 ms after the crossing,
                    # back by 50 ms; semitone slurs and Syrinx hardly), so the change is a smear, not a glide
                    sup.append((tc[i0] + sl * 0.5, 0.006, sdet * SLUR_UP_DB * min(1.0, abs(m - pm) / 3.0)
                                * float(np.exp(srng.normal(0, 0.4)))))
            sc = lane_at('scoop', s_glob, 0.0)
            if sc > 0:
                stime = float(P['scoop_ms']) / 1000 * (0.6 + 0.4 * min(sc, 4) / 4) * np.exp(nrng.normal(0, 0.12))
                curve = np.exp(-t_rel / stime) * (1 - _smooth(t_rel / (4 * stime)))
                bend_extra[i0:] += -sc * curve
                blow_db[i0:] += -3.0 * curve
            fl = lane_at('fall', e_glob - 1, 0.0)
            if fl > 0:
                ftime = float(P['fall_ms']) / 1000 * (0.4 + 0.6 * fl / 12.0) ** 0.7 * np.exp(nrng.normal(0, 0.1))
                ftime = min(ftime, (i1 - i0) * CR / sr * 0.85)
                f0i = i1 - int(ftime * sr / CR)
                x = np.clip((tc[f0i:i1] - tc[f0i]) / max(ftime, 1e-3), 0, 1)
                bend_extra[f0i:i1] += -fl * x ** 1.3
                blow_db[f0i:i1] += -24.0 * x ** 2
                if j == len(ph) - 1 and len(x):
                    bend_extra[i1:] += -fl
                    blow_db[i1:] += -24.0
            if j == len(ph) - 1:
                rel_n = rel * float(np.clip(d / 0.3, 0.35, 1.0))      # a short note: the tongue stops the air
                ir = max(1, int(rel_n * sr / CR))
                tail = np.arange(nc - i1)
                g_end = np.ones(nc)
                g_end[i1:] = np.clip(1 - tail / ir, 0, 1) ** 1.6
                tone *= g_end
                # a short note's release is the tongue stopping the air: all harmonics at once, the air after them
                # as before r7 (staccato, flutter notes of 0.1-0.25 s); the slant in full from 0.5 s
                rsh = float(np.clip((d - 0.25) / 0.25, 0, 1))
                rel_at.append((i1, ir, g_end, REL_UP * rsh))
                # the air outlasts the tone a little at the release (the jet breaks up last)
                ga = np.ones(nc)
                ga[i1:] = np.clip(1 - tail / (ir * (1.3 + (REL_AIR - 1.3) * rsh)), 0, 1) ** 1.2
                airg *= ga
        vel = np.maximum(vel, 1e-3)
        if VEL_GLIDE_MS > 0 and len(ph) > 1:
            al = float(np.exp(-CR / sr / (VEL_GLIDE_MS / 1000)))
            vel = lfilter([1 - al], [1, -al], vel, zi=[al * vel[0]])[0]
        midi_col = midi + COL_GLIDE * glide                     # where the pitch is, for the tables

        gidx_c = np.clip(a + np.arange(nc) * CR, 0, total_n - 1)

        def lc(name, default):
            c = lanes.get(name)
            if c is None or len(c) == 0:
                return np.full(nc, float(default))
            c = np.asarray(c, dtype=np.float64)
            return c[np.clip(gidx_c, 0, len(c) - 1)]

        bend = lc('bend', 0.0)
        vibd = lc('vib', P['vib'])
        vh = float(np.clip(P['vib_hold'], 0.0, 1.0))
        if vh > 0 and lanes.get('vib') is not None and len(lanes.get('vib')) and vhold:
            # each note keeps the vib lane's value at its start (a lane written per note, a point at each note,
            # otherwise ramps down through every long note to the next short one: a song line's late vibrato
            # read 0.4-6.7 c for lane values 8.5-11 c)
            held = np.full(nc, vhold[0][1])
            for i0_, val in vhold:
                held[i0_:] = val
            vibd = vh * held + (1 - vh) * vibd
        lvl = lc('level', 0.0)
        air = np.clip(lc('breath', P['breath']), 0, 1)
        flut = np.clip(lc('flutter', 0.0), 0, 1)

        # ---- vibrato: breath pulses move the pitch and the blowing together; grows into held notes
        vr = float(P['vib_rate']) * (1 + 0.06 * _wander(nc, crate, 1.0, prng))
        vph = 2 * np.pi * np.cumsum(vr / crate) + prng.uniform(0, 2 * np.pi)
        vw = 1 + 0.3 * _wander(nc, crate, 0.7, prng)
        vcy = float(np.clip(P['vib_cycle'], 0.0, 1.0))
        if vcy > 0:
            # cycle to cycle: the real breath pulses differ in length and size (Iowa vib, per cycle: rate cv 0.2,
            # depth cv 0.4), a fast wander on top of the slow ones (the round-4 vibrato was an even sine)
            vr = vr * (1 + vcy * VIB_CYC_RATE * _wander(nc, crate, VIB_CYC_HZ, _rng(seed, ms0, 15)))
            vph = 2 * np.pi * np.cumsum(vr / crate) + float(vph[0])
            vw = np.maximum(vw + vcy * VIB_CYC_DEPTH * _wander(nc, crate, VIB_CYC_HZ, _rng(seed, ms0, 16)), 0.1)
        vdepth = vibd * vsc * vw
        vlev = vibd * vw          # the breath pulse's level swing keeps to the setting (Iowa vib: 1.3-1.9 dB at 4-20 c)
        grow = max(float(P['vib_grow']), 0.02)
        vgate = np.maximum(_smooth((note_age - vdl) / grow), VIB_CARRY * (note_age < note_age.max() + 1))
        vgate = np.where(note_age < 0.04, vgate * _smooth(note_age / 0.04), vgate)
        vgl = np.maximum(_smooth((note_age - vdl) / (1.3 * grow)), VIB_CARRY)   # the air pulse grows a little longer
        vsin = np.sin(vph)
        # the pitch swing is wider when blowing harder (Iowa: pp 4-10 c, mf 10-13, ff 9-20 at one setting)
        b_now = _blow(vel)
        vdyn = np.clip(1 + VIB_DYN * (b_now - FIT_B[1]), 0.4, 1.7)
        vib_c = vdepth * vdyn * vgate * vsin / 100.0
        vib_db = float(P['vib_amp_db']) * vlev / 10.0 * vgl * np.sin(vph + VIB_PHASE)
        vib_gain = 10 ** (VIB_AMP_DB * vlev / 12.0 * vgl * np.sin(vph + VIB_PHASE) / 20)   # the pulse itself

        # ---- blowing (dB re ff)
        frng = _rng(seed, ms0, 8)
        if flut.max() > 0:
            fr_hz = float(P['flutter_rate']) * (1 + 0.1 * _wander(nc, crate, 4.0, frng))
            # the rolls break up (Philharmonia: the roll-to-roll autocorrelation 0.42, ours was 0.82): each roll a
            # little early or late and of its own depth
            fr_hz = fr_hz * np.maximum(1 + FLUT_JIT * _wander(nc, crate, FLUT_JIT_HZ, _rng(seed, ms0, 17)), 0.3)
            fph = 2 * np.pi * np.cumsum(fr_hz / crate)
            flap = (0.5 + 0.5 * np.cos(fph)) ** FLUT_SHAPE
            flap = flap * np.clip(1 + FLUT_AMP_SD * _wander(nc, crate, float(P['flutter_rate']), _rng(seed, ms0, 18)),
                                  0.0, 1.5)
            flut_db = 20 * np.log10(np.maximum(1 - FLUTTER_DEPTH * flut * flap, 0.05))
        else:
            flap = np.zeros(nc)
            flut_db = np.zeros(nc)
        breathe = float(P['breathe_db']) * _wander(nc, crate, 0.8, prng)
        # the flap moves the level as well as the blowing (real flutter gates 0.5-2 kHz most: 7 dB rms against 5-6
        # higher up; through the blowing alone the colour moved more than the level, low bands 3.5 dB)
        b_db = _blow(vel) + lvl + blow_db + breathe + vib_db + (1 - FLUT_LEVEL) * flut_db
        gain_db = gain_db + FLUT_LEVEL * flut_db
        b_db = np.clip(b_db, -40.0, 6.0)

        # ---- pitch: the note, bends, slurs, vibrato, drift, the air's pull (soft flat, loud sharp)
        drift = float(P['drift_cents']) / 100.0 * _wander(nc, crate, 0.6, prng) +             JITTER_CENTS / 100.0 * _wander(nc, crate, 22.0, _rng(seed, ms0, 14))   # the jet's small unsteadiness
        cents_dyn = float(P['intonation']) * (_interp2(FIT_CENTS, midi, b_db) -
                                              _interp2(FIT_CENTS, midi, np.full(nc, FIT_B[1]))) / 100.0
        rel_sag = -0.25 * (1 - tone) * (tone > 0) * (note_age > 0.05)
        m_c = midi + bend + bend_extra + vib_c + drift + cents_dyn + rel_sag
        f0_c = 440.0 * 2 ** ((m_c - 69) / 12)

        # ---- harmonics from the measured tables (level re ff H1 of the note), the tone gate per harmonic
        w_pl = float(np.clip(P['played'], 0.0, 1.0))           # straight-tone set vs the vibrato-played set
        Hk = (1 - w_pl) * _interp2(FIT_H, midi_col, b_db) + w_pl * _interp2(FIT_HV, midi_col, b_db)   # (nc, nh_tab)
        if LEVEL_EVEN:
            Hk = Hk + LEVEL_EVEN * ((1 - w_pl) * _interp2(FIX_H, midi_col, b_db) +
                                    w_pl * _interp2(FIX_HV, midi_col, b_db))[:, None]
        Aband = _interp2(FIT_AIR, midi_col, b_db)              # (nc, 5) dB re the tone's harmonic power
        upi = np.arange(n)
        ci = upi / CR
        i_lo = np.minimum(np.floor(ci).astype(int), nc - 2)
        fr_ = ci - i_lo

        def upc(x):
            return x[i_lo] * (1 - fr_) + x[i_lo + 1] * fr_

        f0 = upc(f0_c)
        ph1 = 2 * np.pi * np.cumsum(f0) / sr
        sig = np.zeros(n)
        kmax = int(min(nh_tab + 8 if TAIL_DB_OCT is None else 60, 15000.0 / max(200.0, float(np.min(f0_c)))))
        if TAIL_DB_OCT is not None:                             # r8: the tail past the table (see TAIL_DB_OCT)
            t_anchor = 0.5 * (Hk[:, nh_tab - 1] + Hk[:, nh_tab - 3:].mean(1))
            t_slope = TAIL_DB_OCT + TAIL_SOFT * np.clip(b_db, -40.0, 0.0) / 10.0
        phases = prng.uniform(-PHASE_SPREAD, PHASE_SPREAD, kmax + 1)
        tilt = float(P['bright'])
        lev_tone = np.zeros(nc)
        for k in range(1, kmax + 1):
            fk = k * f0_c
            if k <= nh_tab:
                adb = Hk[:, k - 1].copy()
            elif TAIL_DB_OCT is not None:                       # r8: past the table, a measured tail law
                adb = t_anchor + t_slope * np.log2(k / nh_tab)
            else:                                               # past the table: continue its last slope
                adb = Hk[:, nh_tab - 1] + (Hk[:, nh_tab - 1] - Hk[:, nh_tab - 3]) / 2 * (k - nh_tab)
            octs = np.log2(np.maximum(fk, 1) / 1000.0)
            adb = adb + tilt * np.where(octs > 0, octs, 0.0)
            if PARTIAL_WANDER_DB > 0 and k > 1:
                pwg = PARTIAL_WANDER_DB * min(1.0, (k - 1) / 3.0)
                if COMB_DB > 0:                                 # r8: slow level wander, each partial its own
                    cg = COMB_DB * min(1.0, (k - 1) / 2.0) * np.clip((COMB_MIDI[1] - midi_col) / (COMB_MIDI[1] - COMB_MIDI[0]), 0, 1)
                    if COMB_B is not None:
                        cg = cg * np.clip((b_db - COMB_B[0]) / (COMB_B[1] - COMB_B[0]), 0, 1)
                    adb = adb + cg * _wander(nc, crate, COMB_HZ, _rng(seed, ms0, 700 + k))
                adb = adb + pwg * _wander(nc, crate, PARTIAL_WANDER_HZ, _rng(seed, ms0, 300 + k)) +                     FLICKER_DB * min(1.0, (k - 1) / 4.0) * _wander(nc, crate, 18.0, _rng(seed, ms0, 500 + k))
            # the attack: upper harmonics arrive later (the jet locks onto the low modes first)
            lagk = lag_c * min(1.0, (k - 1) / 3.0)
            gk = _smooth((tc - tc[0] - lead - inh_len - lagk) / 0.03) if k > 1 else 1.0
            if sup and k >= 3:
                # r6 try 2 thinned H1-H2 over the whole move as well: the slur dip went -6.4 to -9.5 dB (real -6.1)
                # and the smear (flatness) fell, so only H3 up, at the crossing
                tau_k = SLUR_UP_MS / 1000 * (1 + 0.25 * (k - 3))
                for tx, pre, dd in sup:
                    dt = tc - tx
                    env = np.where(dt < 0, _smooth((dt + pre) / pre), np.exp(-np.maximum(dt, 0) / tau_k))
                    adb = adb - dd * min(1.0, (k - 2) / 3.0) * env
            rk = 1.0
            if REL_UP > 0 and k > 1 and rel_at:
                # the upper harmonics stop first: this harmonic's own release gate re the tone's
                i1r, irr, g_e, ru = rel_at[-1]
                tl = np.arange(nc - i1r)
                g_k = np.ones(nc)
                g_k[i1r:] = np.clip(1 - tl / max(1.0, irr / (1 + ru * (k - 1))), 0, 1) ** 1.6
                rk = np.where(g_e > 1e-9, g_k / np.maximum(g_e, 1e-9), 0.0)
            if float(P['tgap_shape']):
                adb = adb + tgap_db * np.clip((TGAP_HZ - fk) / (0.5 * TGAP_HZ), 0, 1)
            amp_k = 10 ** ((adb + gain_db) / 20) * tone * gk * vib_gain * rk
            amp_k[fk > 15000] = 0.0
            amp_k = amp_k * np.clip((16000 - fk) / 3000, 0, 1)
            ghosts = []
            for xi0, xm, xms in xfd:
                # r11 slur_cross: this harmonic of the new note comes in at its own time, the old note's rings on at
                # the old pitch and drops at its own time (each harmonic and slur its own draw)
                xr = _rng(seed, xms, 600 + k)
                dk = max(0.0, SLUR_X_DROP + SLUR_X_DROP_SD * xr.normal())
                rk_ = max(0.0, SLUR_X_RISE + SLUR_X_RISE_SD * xr.normal())
                dt = tc - tc[xi0]
                new_env = np.where(dt < 0, 1.0, _smooth((dt - rk_) / SLUR_X_RAMP))
                a_old = float(amp_k[max(xi0 - 1, 0)])
                amp_k = amp_k * (1 - scr * (1 - new_env))
                fo = k * 440.0 * 2 ** ((xm - 69) / 12)
                if fo < 15000 and a_old > 0:
                    ghosts.append((xi0, a_old * scr, fo, dk))
            lev_tone += amp_k ** 2
            sig += upc(amp_k) * np.sin(k * ph1 + phases[k])
            for xi0, ag, fo, dk in ghosts:
                g0 = max(xi0 - 1, 0) * CR                     # from the frame before: the main tone fades over it
                L_ = min(n - g0, int((dk + 6 * SLUR_X_TAU) * sr) + CR + 1)
                if L_ <= 0:
                    continue
                tt_ = np.arange(L_) / sr
                env = np.minimum(np.arange(L_) / CR, 1.0) * np.exp(-np.maximum(tt_ - CR / sr - dk, 0) / SLUR_X_TAU)
                sig[g0:g0 + L_] += ag * env * np.sin(k * ph1[g0] + phases[k] + 2 * np.pi * fo * tt_)

        # ---- air: band noise at the measured level re the tone (riding the jet, pitch-synchronous in part)
        nrng = _rng(seed, ms0, 3)
        wn = nrng.normal(0, 1, n)
        held_pow = np.sqrt(np.maximum(lev_tone / np.maximum(tone, 1e-3) ** 2, 1e-12))   # tone level without the gate
        sync = 0.6 + 0.4 * (0.5 + 0.5 * np.cos(ph1)) ** 2
        airmix = np.zeros(n)
        # the air brightens with the pitch swing of the vibrato (Iowa vib: the noise over 3 kHz re the harmonics moves
        # with the pitch, r 0.64-0.89, 2.6-5.4 dB at 10-26 c): dB per 10 c of pitch vibrato, full from 3 kHz up
        va = float(P['vib_air'])
        if va != 0:                                         # ... more at pp (G4 pp 3.3 dB per 10 c, mf and ff 2)
            va = va * (1 + VIB_AIR_SOFT * np.clip((FIT_B[1] - _blow(vel)) / 10.0, 0, 1))
        if AIR_SMOOTH:
            # round 6: the measured band levels as a smooth curve. Per band its level per Hz at the band's centre,
            # read in between along log frequency, played by narrow bands of their OWN noise (powers add). The
            # octave bands of one shared noise cancelled where they meet (4, 8 kHz): ours had a hard top edge near
            # 4.3-5.3 kHz and dips at 4.7 and 8.7 kHz; the real noise falls off evenly (measured).
            bc = np.log2([np.sqrt(lo * hi) for lo, hi in AIR_BANDS])
            shd = float(P['air_shade']) if (AIR_SHADE_DB or AIR_SHADE_TILT) else 0.0
            if shd:
                sh_lev = shd * AIR_SHADE_DB * _wander(nc, crate, AIR_SHADE_HZ, _rng(seed, ms0, 90))
                sh_tilt = shd * AIR_SHADE_TILT * _wander(nc, crate, AIR_SHADE_HZ, _rng(seed, ms0, 91))
            dens = Aband - 10 * np.log10([hi - lo for lo, hi in AIR_BANDS])[None, :]      # dB per Hz
            for k_, fcn in enumerate(AIR_NB_HZ):
                if fcn * 2 ** (1 / 6) > sr / 2 - 200:
                    break
                lo, hi = fcn * 2 ** (-1 / 6), fcn * 2 ** (1 / 6)
                x = np.log2(fcn)
                if x <= bc[0]:
                    d_ = dens[:, 0] - AIR_LO_ROLL * (bc[0] - x)
                elif x >= bc[-1]:
                    d_ = dens[:, -1] + np.minimum(dens[:, -1] - dens[:, -2], 0.0) / (bc[-1] - bc[-2]) * (x - bc[-1])
                else:
                    j_ = int(np.searchsorted(bc, x)) - 1
                    f_ = (x - bc[j_]) / (bc[j_ + 1] - bc[j_])
                    d_ = dens[:, j_] * (1 - f_) + dens[:, j_ + 1] * f_
                d_ = d_ - AIR_TOP_ROLL * max(0.0, np.log2(fcn / 12000.0))
                bn = sosfilt(butter(2, (lo, hi), btype='band', fs=sr, output='sos'), _rng(seed, ms0, 40 + k_).normal(0, 1, n))
                g = 10 ** ((d_ + AIR_GAIN_DB) / 20) * held_pow * np.sqrt(sr / 2)
                if shd:
                    g = g * 10 ** ((sh_lev + sh_tilt * np.log2(fcn / 3000.0)) / 20)
                if np.any(va != 0):
                    cpl = va * float(_smooth(np.log2(fcn / 1500.0))) * vib_c * 10.0
                    if VIB_AIR_SPLIT > 0:
                        cpl = cpl * (1 + VIB_AIR_SPLIT * _wander(nc, crate, VIB_AIR_SPLIT_HZ, _rng(seed, ms0, 70 + k_)))
                    g = g * 10 ** (cpl / 20)
                airmix += bn * upc(g)
        else:
            for bi_, (lo, hi) in enumerate(AIR_BANDS):
                bn = sosfilt(butter(2, (lo, min(hi, sr / 2 - 200)), btype='band', fs=sr, output='sos'), wn)
                bw_norm = 1.0                                       # unit-variance white -> band rms ~ sqrt(bw share)
                share = (min(hi, sr / 2) - lo) / (sr / 2)
                g_db = Aband[:, bi_]
                g = 10 ** ((g_db + AIR_GAIN_DB) / 20) * held_pow / np.sqrt(share) * bw_norm
                airmix += bn * upc(g)
        acb = float(P.get('air_comb', 0.0))
        # the comb over AIR_COMB_HZ only, and none at pp (try 1, the whole air at every dynamic: the pp floor went
        # 2-5 dB under the real's and 1-3 kHz at C6 ff too; distance pp C4 +0.57, vib C6 +1.21)
        if acb > 0 and AIR_COMB_TAPS > 0:
            acb = acb * upc(np.clip(1 - (FIT_B[1] - _blow(vel)) / 10.0, 0, 1) * np.ones(nc))
            per = sr / np.maximum(_smooth_f0(f0), 50.0)        # the period, samples
            ii = np.arange(n, dtype=float)
            hi_part = sosfilt(butter(2, AIR_COMB_HZ, btype='high', fs=sr, output='sos'), airmix)
            airmix = airmix - hi_part
            cmb = hi_part.copy()
            gg = 1.0
            pw = 1.0
            gt_ = AIR_COMB_G
            if AIR_COMB_G_HI != AIR_COMB_G:
                ms_ = 69 + 12 * np.log2(np.maximum(_smooth_f0(f0), 50.0) / 440.0)
                gt_ = AIR_COMB_G + (AIR_COMB_G_HI - AIR_COMB_G) * np.clip((ms_ - AIR_COMB_HI_MIDI) / 7.0 + 0.0, 0, 1)
            for m_ in range(1, AIR_COMB_TAPS + 1):
                gg = gg * gt_
                pw += gg * gg
                cmb += gg * np.interp(ii - m_ * per, ii, hi_part, left=0.0)
            airmix = airmix + (1 - acb) * hi_part + acb * cmb / np.sqrt(pw)
        apt = float(P.get('air_patch', 0.0))
        if apt > 0 and AIR_PATCH_DB > 0:
            from scipy.signal import stft as _stft, istft as _istft
            fz, tz, Z = _stft(airmix, fs=sr, nperseg=1024, noverlap=768)
            patch_rng = _rng(seed, ms0, 95)
            nf_ = int(fz[-1] / AIR_PATCH_F) + 2
            nt_ = int(max(tz[-1], AIR_PATCH_T) / AIR_PATCH_T) + 2
            G = patch_rng.normal(0, 1, (nf_, nt_))
            Gf = np.stack([np.interp(fz / AIR_PATCH_F, np.arange(nf_), G[:, j]) for j in range(nt_)], 1)
            Gt = np.stack([np.interp(tz / AIR_PATCH_T, np.arange(nt_), Gf[i]) for i in range(len(fz))], 0)
            Gt = Gt / max(float(np.std(Gt)), 1e-9)
            ramp = np.clip(np.log2(np.maximum(fz, 1.0) / AIR_PATCH_HZ), 0, 1)[:, None]
            # none at pp (as the air comb; try 1 at every dynamic: vib pp G4 5.25 to 6.14, its 1-3 kHz floor 5 dB dark)
            pbl = float(np.mean(np.clip(1 - (FIT_B[1] - _blow(vel)) / 10.0, 0, 1)))
            gdb = apt * pbl * AIR_PATCH_DB * Gt * ramp
            gp = 10 ** (gdb / 10)
            gp = gp / np.exp(np.mean(np.log(gp) ** 2) / 2) ** ramp     # the same mean power (lognormal)
            _, ap = _istft(Z * np.sqrt(gp), fs=sr, nperseg=1024, noverlap=768)
            airmix = np.pad(ap, (0, max(0, n - len(ap))))[:n]
        oct8 = tilt * 2.0
        if tilt != 0:
            airmix *= 10 ** (oct8 * 0.5 / 20)
        air_amt = upc(np.maximum(airg, 0) * (air / 0.5) * np.maximum(1 + air_burst + 0.8 * flut * flap, 0.05))
        sig += airmix * sync * air_amt

        # the tongue's chiff, the keys' thump, the inhale
        sosh = butter(2, 1200.0, btype='high', fs=sr, output='sos')
        hp_ref = float(np.median(held_pow[held_pow > 1e-9])) if (held_pow > 1e-9).any() else 0.0
        for ch in chiff:
            i0, strength = ch[0], ch[1]
            if strength <= 0:
                continue
            s0 = i0 * CR
            if s0 >= n:
                continue
            if len(ch) > 2:
                # a legato tongue: the air puff after the tongue lifts is a low band of noise (Philharmonia legato:
                # the change's noise sits 0.5-3 kHz, centroid about 1.3 kHz, and differs note to note), drawn per note
                crng = _rng(seed, ch[2], 21)
                fc = float(np.clip(LEG_PUFF_HZ * np.exp(crng.normal(0, 0.4)), 500.0, 3200.0))
                bw = float(np.clip(crng.uniform(0.9, 1.8), 0.5, 2.5))            # octaves
                lo_, hi_ = fc / 2 ** (bw / 2), min(fc * 2 ** (bw / 2), sr / 2 - 200)
                tau = LEG_PUFF_MS / 1000 * np.exp(crng.normal(0, 0.3))
                L = int(min(4 * tau, 0.08) * sr)
                e = min(n, s0 + L)
                w = sosfilt(butter(2, (lo_, hi_), btype='band', fs=sr, output='sos'), crng.normal(0, 1, e - s0))
                k_ = np.arange(e - s0)
                envc = np.exp(-k_ / (tau * sr)) * (1 - np.exp(-k_ / (0.002 * sr)))
                g_ = 10 ** ((LEG_PUFF_DB + crng.normal(0, 3.0)) / 20)
                sig[s0:e] += w * envc * strength * 0.35 * hp_ref * g_
                # the tongue's own click rides on it, its level different every note
                strength = strength * 10 ** ((LEG_CLICK_DB + crng.normal(0, 4.0)) / 20)
            ctau = CHIFF_MS / 3000                                         # s
            L = int(max(CHIFF_MS / 1000 * 2, 4 * ctau) * sr)
            e = min(n, s0 + L)
            w = sosfilt(sosh, nrng.normal(0, 1, e - s0))
            envc = np.exp(-np.arange(e - s0) / (ctau * sr)) * (1 - np.exp(-np.arange(e - s0) / (0.0008 * sr)))
            sig[s0:e] += w * envc * strength * 0.35 * hp_ref
        for xi0, xm, xms in xfd:
            # r11 slur_cross: the breath burst at the join (the jet re-forms on the new note)
            s0 = xi0 * CR
            crng = _rng(seed, xms, 23)
            tau = SLUR_X_NZ_MS / 1000 * float(np.exp(crng.normal(0, 0.3)))
            L = min(n - s0, int(4 * tau * sr))
            if L <= 0:
                continue
            w = sosfilt(butter(2, (SLUR_X_NZ_HZ[0], min(SLUR_X_NZ_HZ[1], sr / 2 - 200)), btype='band', fs=sr, output='sos'), crng.normal(0, 1, L))
            k_ = np.arange(L)
            envc = np.exp(-k_ / (tau * sr)) * (1 - np.exp(-k_ / (0.002 * sr)))
            if SLUR_X_SOFT_DB > -150:
                sg = SLUR_X_SOFT_MS / 1000
                Ls = min(n - s0, int(4 * sg * sr))
                ws = sosfilt(butter(4, (SLUR_X_SOFT_LO, SLUR_X_SOFT_HI), btype='band', fs=sr, output='sos'), crng.normal(0, 1, Ls))
                es = np.exp(-(np.arange(Ls) / (sg * sr) - 2.0) ** 2)
                sig[s0:s0 + Ls] += ws * es * scr * 0.35 * hp_ref * 10 ** ((SLUR_X_SOFT_DB + 3.0 * crng.normal()) / 20)
            sig[s0:s0 + L] += SLUR_X_BURST * w * envc * scr * 0.35 * hp_ref * 10 ** ((SLUR_X_NZ_DB + 3.0 * crng.normal()) / 20)
        kk = float(P['keys'])
        if kk > 0 and keyt:
            sosk = butter(2, (150.0, 900.0), btype='band', fs=sr, output='sos')
            for i0 in keyt:
                s0 = i0 * CR
                L = int(0.012 * sr)
                if s0 + L >= n:
                    continue
                w = sosfilt(sosk, nrng.normal(0, 1, L))
                sig[s0:s0 + L] += w * np.exp(-np.arange(L) / (0.003 * sr)) * kk * 0.08 * hp_ref
        if do_inhale:
            irng = _rng(seed, ms0, 9)
            L = int(inh_len * sr)
            s0 = max(0, int((lead + inh_len) * sr) - L - int(0.06 * sr))
            if L > 0 and s0 + L <= n:
                w = irng.normal(0, 1, L)
                w = sosfilt(butter(2, (700.0, 5000.0), btype='band', fs=sr, output='sos'), w)
                x = np.arange(L) / L
                envi = np.sin(np.pi * x) ** 1.5 * (0.7 + 0.3 * x)
                sig[s0:s0 + L] += w * envi * inh * 10 ** (INHALE_DB / 20) * hp_ref * 3.0

        s0, e0 = max(0, a), min(total_n, b)
        out[s0:e0] += sig[s0 - a:e0 - a]

    out *= 0.25 * float(P['level'])
    room = float(P['room'])
    L = out.copy()
    R = out.copy()
    if room > 0:
        for d_ms, g, side in ((5.7, 0.3, 0), (9.3, 0.24, 1), (14.1, 0.19, 0), (21.7, 0.15, 1), (28.3, 0.1, 0),
                              (34.9, 0.08, 1)):
            dn = int(d_ms / 1000 * sr)
            tgt = L if side == 0 else R
            tgt[dn:] += room * g * out[:-dn]
    if float(P['floor_db']) > -150:
        t_start = beat0 * 60.0 / bpm
        i0 = int(round(t_start * sr))
        b_first, b_last = i0 // sr, (i0 + total_n - 1) // sr
        # the shape of the Iowa MIS room floor (quiet stretches of the flute files, re the 1-4 kHz band):
        # 20-60 Hz +13 dB, 60-200 +7, 200-1k +4.5, 4-12k +1, 12-20k -1 (fit: 10, 7.5, 3.3, -0.3, -0.9)
        sos_r = butter(2, 70.0, btype='low', fs=sr, output='sos')
        sos_b = butter(1, 400.0, btype='low', fs=sr, output='sos')
        fl = np.zeros(total_n)
        for blk in range(b_first, b_last + 1):
            w = np.concatenate([_rng(seed, blk - 1, 7).normal(0, 1, sr), _rng(seed, blk, 7).normal(0, 1, sr)])
            w = (76.16 * sosfilt(sos_r, w) + 12.6 * sosfilt(sos_b, w) + 1.563 * w)[sr:]
            a = blk * sr - i0
            s0, e0 = max(0, a), min(total_n, a + sr)
            if e0 > s0:
                fl[s0:e0] = w[s0 - a:e0 - a]
        fl *= 10 ** (float(P['floor_db']) / 20) / (5.674 * np.sqrt(44100.0 / sr))      # floor_db = its rms
        L += fl
        R += fl
    return np.vstack([L, R])
